package com.projetok.studio;
import javax.swing.*;import java.awt.*;import java.awt.event.*;import java.awt.image.*;import java.nio.file.*;import java.util.*;import java.util.function.Supplier;import javax.imageio.ImageIO;import com.projetok.prototype.*;
public class StudioUiProbe {
 static WorldStudio editor;static JFrame game;static DebugPanel panel;static Supplier<DebugSnapshot> snapshot;static int phase,watch;static long tick;static float before;static Path out,project;
 static DebugPanel find(Container c){for(Component x:c.getComponents()){if(x instanceof DebugPanel p)return p;if(x instanceof Container child){var p=find(child);if(p!=null)return p;}}return null;}
 static void capture(JFrame f,String name)throws Exception{var image=new BufferedImage(f.getWidth(),f.getHeight(),1);var g=image.createGraphics();f.printAll(g);g.dispose();ImageIO.write(image,"png",out.resolve(name+".png").toFile());}
 public static void main(String[] args)throws Exception{out=Path.of(args[0]).toAbsolutePath();project=Path.of("").toAbsolutePath();Files.createDirectories(out);SwingUtilities.invokeAndWait(()->{editor=new WorldStudio(project);editor.setVisible(true);editor.rescan();var timer=new javax.swing.Timer(60,e->{try{step();}catch(Exception error){error.printStackTrace();System.exit(2);}});timer.start();});}
 @SuppressWarnings("unchecked") static void step()throws Exception{if(++watch>700)throw new IllegalStateException("UI timeout phase "+phase);
 if(phase==0&&editor.refresh.isEnabled()&&!editor.catalog.assets().isEmpty()){
  var d=WorldDocument.empty("studio_probe",960,640);var spawn=new WorldDocument.Element("player",WorldDocument.Kind.PLAYER,"","",new WorldDocument.Crop(0,0,32,32),140,320,32,32,"interaction",true,false,"","FRONT",Map.of());d=d.withElements(java.util.List.of(spawn)).withHitboxes(java.util.List.of(new WorldDocument.Hitbox("wall",260,280,32,128,true,"collision")));editor.change(d);DocumentStore.save(out.resolve("studio_probe.sgmap"),d);capture(editor,"editor");var path=StudioExport.write(out.resolve("export"),d.id(),Map.of(d.id(),d),editor.catalog);phase=1;new Thread(()->{try{StudioPlaytest.launch(path,project);}catch(Exception error){error.printStackTrace();System.exit(2);}}).start();
 }else if(phase==1){for(Frame f:Frame.getFrames())if(f instanceof JFrame j&&j.isShowing()&&j.getTitle().contains("PLAYTEST ISOLADO")){game=j;panel=find(game);var field=DebugPanel.class.getDeclaredField("source");field.setAccessible(true);snapshot=(Supplier<DebugSnapshot>)field.get(panel);tick=snapshot.get().ticks();before=snapshot.get().actors().get(0).x();panel.getActionMap().get("Dtrue").actionPerformed(new ActionEvent(panel,0,"probe"));phase=2;return;}}
 else if(phase==2&&snapshot.get().ticks()-tick>=30){panel.getActionMap().get("Dfalse").actionPerformed(new ActionEvent(panel,0,"probe"));float x=snapshot.get().actors().get(0).x();if(!(x>before&&x<=242.01))throw new IllegalStateException("Collision failed "+x);capture(game,"playtest-real");Files.writeString(out.resolve("evidence.json"),"{\"catalogAssets\":"+editor.catalog.assets().size()+",\"initialX\":"+before+",\"blockedX\":"+x+",\"realWindow\":true,\"realRuntime\":true,\"humanApproved\":false}");phase=3;game.dispatchEvent(new WindowEvent(game,WindowEvent.WINDOW_CLOSING));editor.dispose();new javax.swing.Timer(400,e->System.exit(0)).start();}
 }
}
